def find_amqp_behaviors(
    behaviors: list[Behavior],
    exchange: str,
    routing_key: str,
    queue_name: str,
    payload: str,
    redis_store: RedisStore | None = None,
) -> list[Behavior]:
    matches: list[Behavior] = []
